 <section class="ex-screen" data-panel="share"><div class="row g-3"><div class="col-lg-7"><div class="ex-card h-100"><div class="ex-head"><h2><span class="ex-title-icon"><i class="ti ti-bell-ringing"></i></span>Notify and Share</h2></div><div class="ex-body"><div id="shareSuccess" class="ex-pass mb-3"><strong><i class="ti ti-circle-check me-1"></i>Published timetable ready to share</strong><div class="small mt-1">Choose the authorized audiences to record notifications.</div></div><div class="ex-check-grid mb-3" id="audienceChecks"></div><label class="form-label">Message</label><textarea id="shareMessage" class="form-control" rows="3" maxlength="500" placeholder="The exam timetable is now available. Please review your assigned dates, rooms, and times."></textarea><button class="btn btn-primary w-100 mt-3" id="sendBtn"><i class="ti ti-send me-1"></i>Send Notifications</button></div></div></div><div class="col-lg-5"><div class="ex-card h-100"><div class="ex-head"><h2><span class="ex-title-icon"><i class="ti ti-file-export"></i></span>Share / Export</h2></div><div class="ex-body d-grid gap-2"><button class="btn btn-outline-primary" id="printBtn"><i class="ti ti-printer me-1"></i>Print / Save as PDF</button><button class="btn btn-outline-primary" id="excelBtn"><i class="ti ti-file-spreadsheet me-1"></i>Export to Excel (CSV)</button><button class="btn btn-outline-secondary" id="shareHistoryBtn"><i class="ti ti-history me-1"></i>View Share History</button><button class="btn btn-outline-secondary" data-go="dashboard"><i class="ti ti-layout-dashboard me-1"></i>Back to Dashboard</button></div></div></div></div></section>
</div>

<div class="modal fade" id="adjustModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="ti ti-edit text-primary me-2"></i>Adjust Exam Entry</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="aId"><div id="aHeading" class="fw-bold mb-3"></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Exam Date *</label><input id="aDate" type="date" class="form-control"></div><div class="col-md-6"><label class="form-label">Exam Time Block *</label><select id="aBlock" class="form-select"></select></div><div class="col-md-6"><label class="form-label">Room *</label><select id="aRoom" class="form-select"></select></div><div class="col-md-6"><label class="form-label">Proctor *</label><select id="aTeacher" class="form-select"></select></div><div class="col-12"><label class="form-label">Adjustment Remarks</label><input id="aRemarks" class="form-control" maxlength="255" placeholder="Reason for adjustment"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" id="saveAdjust"><i class="ti ti-device-floppy me-1"></i>Update Draft</button></div></div></div></div>
<div class="modal fade" id="historyModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><i class="ti ti-history text-primary me-2"></i>Exam Timetable History</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="historyBody"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">Close</button></div></div></div></div>

<script>
(()=>{'use strict';const BASE='<?= BASE_URL ?>',API=BASE+'/api/scheduling/exam-workflow.php',CC=BASE+'/api/scheduling/conflict-check.php';let S={batches:[],summary:{},options:{},batch:null,run:null};const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');let adjustModal;
function alertMsg(msg,kind='info'){const b=$('exAlert');b.className='alert mt-3 alert-'+kind;$('exAlertIcon').className='ti '+(kind==='success'?'ti-circle-check':kind==='danger'?'ti-alert-triangle':'ti-info-circle')+' me-2';$('exAlertText').textContent=msg;b.classList.remove('d-none');window.scrollTo({top:0,behavior:'smooth'});}function hideAlert(){$('exAlert').classList.add('d-none');}
async function request(url,body=null){const r=await fetch(url,{method:body?'POST':'GET',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({ok:false,error:'The server returned an unreadable response.'}));if(!r.ok||!d.ok)throw new Error(d.error||'Request failed.');return d;}
function slug(v){return String(v||'').toLowerCase().replace(/[^a-z]+/g,'-').replace(/^-|-$/g,'');}function pill(v){return `<span class="ex-pill p-${slug(v)}">${esc(v)}</span>`;}function fmtDate(d){return d?new Date(d+'T00:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not scheduled';}function fmtTime(t){if(!t)return'—';const [h,m]=t.slice(0,5).split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function go(name){document.querySelectorAll('.ex-screen').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));const steps=[...document.querySelectorAll('.ex-step')],idx=steps.findIndex(x=>x.dataset.screen===name);steps.forEach((x,i)=>{x.classList.toggle('active',i===idx);x.classList.toggle('done',i<idx)});if(name==='preview')renderPreview();if(name==='adjust')renderAdjust();if(name==='publish')renderPublish();if(name==='share')renderShare();hideAlert();window.scrollTo({top:0,behavior:'smooth'});}
function renderDashboard(){const s=S.summary;$('sTotal').textContent=s.total||0;$('sDraft').textContent=s.draft||0;$('sValidation').textContent=s.validation||0;$('sReady').textContent=s.ready||0;$('sPublished').textContent=s.published||0;const q=$('dashSearch').value.toLowerCase(),type=$('dashType').value,status=$('dashStatus').value,rows=S.batches.filter(b=>(!q||[b.reference_no,b.title,b.academic_year,b.semester].join(' ').toLowerCase().includes(q))&&(!type||b.exam_type===type)&&(!status||b.status===status));$('batchRows').innerHTML=rows.length?rows.map(b=>`<tr><td><strong class="text-primary">${esc(b.reference_no)}</strong><div class="small text-muted">${esc(b.title)}</div></td><td>${esc(b.exam_type)}</td><td>${esc(b.academic_year)}<div class="small text-muted">${esc(b.semester)}</div></td><td>${b.date_from?fmtDate(b.date_from)+' – '+fmtDate(b.date_to):'Not configured'}</td><td>${Number(b.entry_count)}<div class="small text-muted">${Number(b.unscheduled_count)} unscheduled</div></td><td>${pill(b.status)}</td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-view="${b.id}"><i class="ti ti-eye me-1"></i>Open</button></td></tr>`).join(''):'<tr><td colspan="7" class="ex-empty"><i class="ti ti-calendar-off fs-2 d-block mb-2"></i>No exam timetables match the filters.</td></tr>';$('batchRows').querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>openBatch(Number(x.dataset.view)));}
function fillOptions(){const o=S.options;$('dashType').innerHTML='<option value="">All exam types</option>'+o.types.map(x=>`<option>${esc(x)}</option>`).join('');$('fType').innerHTML=o.types.map(x=>`<option>${esc(x)}</option>`).join('');$('fYear').innerHTML=o.academic_years.map(x=>`<option>${esc(x)}</option>`).join('');$('fSemester').innerHTML=o.semesters.map(x=>`<option>${esc(x)}</option>`).join('');$('oProgram').innerHTML='<option value="">All Programs</option>'+o.programs.map(x=>`<option>${esc(x)}</option>`).join('');$('blockChoices').innerHTML=o.time_blocks.length?o.time_blocks.map(x=>`<div class="ex-block"><label><input class="form-check-input me-2 ex-block-check" type="checkbox" value="${x.id}" checked>${esc(x.code)}</label><small>${fmtTime(x.start_time)} – ${fmtTime(x.end_time)} · ${esc(x.label)}</small></div>`).join(''):'<div class="alert alert-warning mb-0"><i class="ti ti-alert-triangle me-1"></i>No active Exam blocks. Create them in Time Block Generator first.</div>';$('weekdayChecks').innerHTML=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<label class="small"><input class="form-check-input me-1 ex-day-check" type="checkbox" value="${d}">${d.slice(0,3)}</label>`).join('');$('engineName').textContent=o.engine.active;$('engineNote').textContent=o.engine.note;$('engineBadge').innerHTML=`<i class="ti ti-cpu"></i>${o.engine.available?'OR-Tools available':'Fallback active'}`;$('engineBadge').className='ex-pill '+(o.engine.available?'p-validated':'p-warning');const roomOpts=o.rooms.filter(r=>r.status==='Available').map(r=>`<option value="${r.id}">${esc(r.room_code)} · ${r.capacity} seats · ${esc(r.room_type)}</option>`).join(''),teacherOpts=o.teachers.filter(t=>t.status==='Active').map(t=>`<option value="${t.id}">${esc(t.full_name)} · ${esc(t.department)}</option>`).join(''),blockOpts=o.time_blocks.map(t=>`<option value="${t.id}">${esc(t.code)} · ${fmtTime(t.start_time)} – ${fmtTime(t.end_time)}</option>`).join('');$('aRoom').innerHTML=roomOpts;$('aTeacher').innerHTML=teacherOpts;$('aBlock').innerHTML=blockOpts;}
async function load(){try{const d=await request(API+'?action=bootstrap');S={...S,...d};fillOptions();renderDashboard();}catch(e){alertMsg(e.message,'danger');}}
function resetDetails(){S.batch=null;S.run=null;['fTitle','fFrom','fTo'].forEach(id=>$(id).value='');if(S.options.types?.length)$('fType').value=S.options.types.includes('Final')?'Final':S.options.types[0];if(S.options.academic_years?.length)$('fYear').value=S.options.academic_years[0];$('fSemester').value='1st Semester';}
async function openBatch(id){try{const d=await request(API+'?action=batch&id='+id);S.batch=d.batch;S.run=null;$('fTitle').value=S.batch.title;$('fType').value=S.batch.exam_type;$('fYear').value=S.batch.academic_year;$('fSemester').value=S.batch.semester;$('fFrom').value=S.batch.date_from||'';$('fTo').value=S.batch.date_to||'';const target=S.batch.status==='Draft'?'details':S.batch.status==='Published'?'share':S.batch.status==='Ready to Publish'?'publish':S.batch.status==='Validated'?'publish':'preview';go(target);}catch(e){alertMsg(e.message,'danger');}}
async function refreshBatch(){if(!S.batch)return;const d=await request(API+'?action=batch&id='+S.batch.id);S.batch=d.batch;return S.batch;}
async function saveDetails(){try{const d=await request(API,{action:'save_setup',id:S.batch?.id||0,title:$('fTitle').value,exam_type:$('fType').value,academic_year:$('fYear').value,semester:$('fSemester').value,date_from:$('fFrom').value,date_to:$('fTo').value});S.batch=d.batch;go('options');alertMsg(d.message,'success');await load();}catch(e){alertMsg(e.message,'danger');}}
function optionPayload(){return{action:'generate',batch_id:S.batch?.id||0,include_regular:$('oRegular').checked?1:0,include_special:$('oSpecial').checked?1:0,reuse_rooms:$('oReuseRooms').checked?1:0,auto_rooms:$('oAutoRooms').checked?1:0,balance_days:$('oBalance').checked?1:0,minimize_room_changes:$('oRoomChanges').checked?1:0,program:$('oProgram').value,min_gap_minutes:Number($('oGap').value),max_per_day:Number($('oMax').value),time_block_ids:[...document.querySelectorAll('.ex-block-check:checked')].map(x=>Number(x.value)),excluded_weekdays:[...document.querySelectorAll('.ex-day-check:checked')].map(x=>x.value)};}
async function generate(){if(!S.batch){alertMsg('Save exam details first.','warning');return;}const btn=$('generateBtn'),old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Generating Draft...';try{const d=await request(API,optionPayload());S.batch=d.batch;S.run=null;go('preview');alertMsg(d.message,'success');await load();}catch(e){alertMsg(e.message,'danger');}finally{btn.disabled=false;btn.innerHTML=old;}}
function previewRecords(){if(!S.batch)return[];const p=$('previewProgram').value,d=$('previewDate').value;return S.batch.records.filter(r=>(!p||r.program===p)&&(!d||r.exam_date===d));}
function renderPreview(){if(!S.batch){$('previewRows').innerHTML='<tr><td colspan="7" class="ex-empty">Create or open a timetable first.</td></tr>';return;}const r=S.batch.records,scheduled=r.filter(x=>x.exam_date).length,gen=S.batch.options?.generation||{};$('previewMeta').innerHTML=[['Reference',S.batch.reference_no],['Term',S.batch.academic_year+' · '+S.batch.semester],['Exam Type',S.batch.exam_type],['Draft Entries',r.length]].map(x=>`<div class="ex-mini"><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('');$('generationNote').innerHTML=`<i class="ti ti-cpu me-1"></i><strong>${esc(S.batch.solver_engine||'Not generated')}</strong> · ${scheduled} scheduled, ${r.length-scheduled} require adjustment. ${esc(gen.engine_note||'All generated records remain Draft until validated and published.')}`;const programs=[...new Set(r.map(x=>x.program).filter(Boolean))],dates=[...new Set(r.map(x=>x.exam_date).filter(Boolean))];$('previewProgram').innerHTML='<option value="">All Programs</option>'+programs.map(x=>`<option>${esc(x)}</option>`).join('');$('previewDate').innerHTML='<option value="">All Dates</option>'+dates.map(x=>`<option value="${x}">${fmtDate(x)}</option>`).join('');const rows=previewRecords();$('previewRows').innerHTML=rows.length?rows.map(x=>`<tr><td>${fmtDate(x.exam_date)}<div class="small text-muted">${fmtTime(x.start_time)} – ${fmtTime(x.end_time)} · ${esc(x.time_block_code||'No block')}</div></td><td><strong>${esc(x.subject_code)}</strong><div class="small text-muted">${esc(x.subject_name)}</div></td><td>${esc(x.section_code)}</td><td>${esc(x.proctor_name||'Not assigned')}</td><td>${esc(x.room_code||'Not assigned')}</td><td>${x.capacity?x.current_students+' / '+x.capacity:'—'}</td><td>${pill(x.exam_date?'Draft':'Needs adjustment')}</td></tr>`).join(''):'<tr><td colspan="7" class="ex-empty">No entries match this preview filter.</td></tr>';}
async function runValidation(recheck=false){if(!S.batch||!S.batch.records.length){alertMsg('Generate a draft timetable first.','warning');return;}const btn=recheck?$('recheckBtn'):$('validateBtn'),old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Checking...';try{const payload={action:recheck?'recheck':'run',previous_run_id:recheck&&S.run?S.run.run_id:'',record_keys:S.batch.records.map(x=>'Exam:'+x.id),academic_year:S.batch.academic_year,semester:S.batch.semester,schedule_type:'Exam'};let d=await request(CC,payload);S.run=d.run;if(Number(d.summary.critical)===0){const c=await request(CC,{action:'complete',run_id:S.run.run_id});S.run=c.run;}const sync=await request(API,{action:'sync_validation',batch_id:S.batch.id,run_id:S.run.run_id});S.batch=sync.batch;renderValidation();go('validate');alertMsg(sync.message,Number(S.run.critical_count)>0?'warning':'success');await load();}catch(e){alertMsg(e.message,'danger');}finally{btn.disabled=false;btn.innerHTML=old;}}
function renderValidation(){const r=S.run;if(!r){['vSelected','vTotal','vCritical','vWarnings','vResolved'].forEach(x=>$(x).textContent='0');$('findingRows').innerHTML='';return;}$('vSelected').textContent=r.selected_count||0;$('vTotal').textContent=r.findings_count||0;$('vCritical').textContent=r.critical_count||0;$('vWarnings').textContent=r.warning_count||0;$('vResolved').textContent=r.resolved_count||0;$('validationState').innerHTML=Number(r.critical_count)>0?`<i class="ti ti-alert-triangle me-1"></i><strong>${r.critical_count} critical conflict(s)</strong> prevent publication. Adjust the affected exams and recheck.`:`<i class="ti ti-circle-check me-1"></i><strong>No critical conflicts remain.</strong> The Conflict Checker result is complete.`;$('findingRows').innerHTML=r.findings?.length?r.findings.map(f=>`<div class="ex-finding ${f.severity==='Warning'?'warning':''}"><div class="d-flex justify-content-between"><h4>${esc(f.conflict_type)} · ${esc(f.section_code||'Exam')}</h4>${pill(f.severity)}</div><p><strong>What:</strong> ${esc(f.message)}<br><strong>Why:</strong> ${esc(f.explanation)}</p><small><i class="ti ti-tool me-1"></i>${esc(f.recommended_action)}</small></div>`).join(''):'<div class="ex-pass"><strong><i class="ti ti-circle-check me-1"></i>No conflicts found</strong><div class="small mt-1">Every selected exam passed the shared validation rules.</div></div>';}
function renderAdjust(){if(!S.batch)return;$('adjustRows').innerHTML=S.batch.records.map(x=>`<tr><td><strong>${esc(x.subject_code)}</strong><div class="small text-muted">${esc(x.section_code)}</div></td><td>${fmtDate(x.exam_date)}</td><td>${esc(x.time_block_code||'Not assigned')}<div class="small text-muted">${fmtTime(x.start_time)} – ${fmtTime(x.end_time)}</div></td><td>${esc(x.room_code||'Not assigned')}</td><td>${esc(x.proctor_name||'Not assigned')}</td><td>${pill(x.status)}</td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-adjust="${x.id}" ${S.batch.status==='Published'?'disabled':''}><i class="ti ti-edit"></i></button></td></tr>`).join('');$('adjustRows').querySelectorAll('[data-adjust]').forEach(x=>x.onclick=()=>openAdjust(Number(x.dataset.adjust)));}
function openAdjust(id){const r=S.batch.records.find(x=>Number(x.id)===id);if(!r)return;$('aId').value=r.id;$('aHeading').textContent=r.subject_code+' · '+r.section_code;$('aDate').value=r.exam_date||S.batch.date_from;$('aBlock').value=r.time_block_id||'';$('aRoom').value=r.room_id||'';$('aTeacher').value=r.proctor_id||'';$('aRemarks').value='';adjustModal.show();}
async function saveAdjust(){try{const d=await request(API,{action:'adjust',id:Number($('aId').value),exam_date:$('aDate').value,time_block_id:Number($('aBlock').value),room_id:Number($('aRoom').value),proctor_id:Number($('aTeacher').value),remarks:$('aRemarks').value});S.batch=d.batch;S.run=null;adjustModal.hide();renderAdjust();alertMsg(d.message,'success');}catch(e){alertMsg(e.message,'danger');}}
function renderPublish(){if(!S.batch)return;const r=S.batch.records,valid=S.batch.status==='Validated'||S.batch.status==='Ready to Publish'||S.batch.status==='Published';$('publishSummary').innerHTML=[['Reference',S.batch.reference_no],['Timetable',S.batch.title],['Exam Entries',r.length],['Status',S.batch.status]].map(x=>`<div class="ex-mini"><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('');$('publishState').innerHTML=valid?`<i class="ti ti-shield-check me-1"></i>Validation result: <strong>${esc(S.batch.validation_run_id||'completed')}</strong>. Publication will perform one final real-time recheck.`:`<i class="ti ti-alert-triangle me-1"></i>This timetable must pass the Conflict Checker before it can be published.`;$('readyBtn').disabled=S.batch.status!=='Validated';$('publishBtn').disabled=S.batch.status!=='Ready to Publish';}
async function markReady(){try{const d=await request(API,{action:'mark_ready',batch_id:S.batch.id});S.batch=d.batch;renderPublish();alertMsg(d.message,'success');}catch(e){alertMsg(e.message,'danger');}}
async function publish(){if(!confirm('Publish this validated exam timetable? Published entries become read-only and available for sharing.'))return;try{const d=await request(API,{action:'publish',batch_id:S.batch.id});S.batch=d.batch;go('share');alertMsg(d.message,'success');await load();}catch(e){alertMsg(e.message,'danger');}}
function renderShare(){if(!S.batch)return;$('shareSuccess').innerHTML=`<strong><i class="ti ti-circle-check me-1"></i>${esc(S.batch.title)}</strong><div class="small mt-1">${esc(S.batch.reference_no)} · ${esc(S.batch.status)} · ${S.batch.records.length} entries</div>`;$('audienceChecks').innerHTML=['Faculty','Students/Sections','Program Heads','Scheduling Staff'].map(a=>`<div class="ex-check-option"><label><input class="form-check-input me-2 audience-check" type="checkbox" value="${a}" checked><i class="ti ti-bell me-1"></i>${a}</label></div>`).join('');}
async function share(){try{const audiences=[...document.querySelectorAll('.audience-check:checked')].map(x=>x.value),d=await request(API,{action:'share',batch_id:S.batch.id,audiences,message:$('shareMessage').value});S.batch=d.batch;alertMsg(d.message,'success');}catch(e){alertMsg(e.message,'danger');}}
function exportCsv(){if(!S.batch)return;const rows=[['Reference','Title','Exam Type','Academic Year','Semester'],[S.batch.reference_no,S.batch.title,S.batch.exam_type,S.batch.academic_year,S.batch.semester],[],['Date','Time Block','Subject','Section','Program','Proctor','Room','Status'],...S.batch.records.map(x=>[x.exam_date||'',x.time_block_code||'',x.subject_code,x.section_code,x.program,x.proctor_name||'',x.room_code||'',x.status])],csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=(S.batch.reference_no||'exam-timetable')+'.csv';a.click();URL.revokeObjectURL(a.href);}
function showHistory(){const h=S.batch?.history||[];$('historyBody').innerHTML=h.length?h.map(x=>`<div class="ex-history"><strong>${esc(x.action)} ${x.from_status?'· '+esc(x.from_status)+' → '+esc(x.to_status):''}</strong><p>${esc(x.detail)}</p><small>${esc(x.changed_by_name)} · ${new Date(String(x.created_at).replace(' ','T')).toLocaleString()}</small></div>`).join(''):'<div class="ex-empty">Open a timetable to view its history.</div>';bootstrap.Modal.getOrCreateInstance($('historyModal')).show();}
document.addEventListener('DOMContentLoaded',()=>{
 adjustModal=new bootstrap.Modal($('adjustModal'));
 document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));
 document.querySelectorAll('.ex-step').forEach(x=>x.onclick=()=>go(x.dataset.screen));
 $('newBtn').onclick=()=>{resetDetails();go('details')};
 $('saveDetails').onclick=saveDetails;
 $('generateBtn').onclick=generate;
 $('listView').onclick=renderPreview;
 $('validateBtn').onclick=()=>runValidation(false);
 $('recheckBtn').onclick=()=>runValidation(true);
 $('adjustRecheck').onclick=()=>{go('validate');runValidation(!!S.run)};
 $('saveAdjust').onclick=saveAdjust;
 $('readyBtn').onclick=markReady;
 $('publishBtn').onclick=publish;
 $('sendBtn').onclick=share;
 $('printBtn').onclick=()=>window.print();
 $('excelBtn').onclick=exportCsv;
 $('exportDraft').onclick=exportCsv;
 $('historyBtn').onclick=showHistory;
 $('shareHistoryBtn').onclick=showHistory;
 ['dashSearch','dashType','dashStatus'].forEach(id=>$(id).addEventListener('input',renderDashboard));
 ['previewProgram','previewDate'].forEach(id=>$(id).addEventListener('change',()=>{
  const p=$('previewProgram').value,d=$('previewDate').value;
  const rows=S.batch.records.filter(r=>(!p||r.program===p)&&(!d||r.exam_date===d));
  $('previewRows').innerHTML=rows.map(x=>`<tr><td>${fmtDate(x.exam_date)}<div class="small text-muted">${fmtTime(x.start_time)} – ${fmtTime(x.end_time)}</div></td><td>${esc(x.subject_code)}</td><td>${esc(x.section_code)}</td><td>${esc(x.proctor_name||'Not assigned')}</td><td>${esc(x.room_code||'Not assigned')}</td><td>${x.capacity?x.current_students+' / '+x.capacity:'—'}</td><td>${pill(x.status)}</td></tr>`).join('')||'<tr><td colspan="7" class="ex-empty">No matching entries.</td></tr>';
 }));
 load();
});
})();
</script>
